/** The themes a deck can name (decision-19): their names, the shapes the folder
 *  and `lib/deck` exchange, and which theme a deck naming none is drawn with.
 *  Pure, and light: what reads a theme's CSS is `lib/slide-theme-css`, kept apart
 *  so postcss loads only when a folder is read, and `lib/slide-theme-folder` is
 *  the Tauri half. */

/** mallow's slide theme, generated by `lib/deck` (decision-18 §5). */
export const MALLOW_THEME = 'default';

/** `kinari` is held for mallow's copy of a kinari release (decision-19 §7), so a
 *  folder theme can never take the name before the copy arrives. */
export const RESERVED_THEME_NAMES: readonly string[] = [MALLOW_THEME, 'kinari'];

/** One `@size` entry, as CSS lengths. */
export interface SlideSize {
  width: string;
  height: string;
}

/** A theme other than mallow's, as `lib/deck` registers it. */
export interface DeckTheme {
  name: string;
  css: string;
  /** The theme's `@size` entries by name, prototype-less so a size named
   *  `constructor` is not mistaken for one. */
  sizes: Readonly<Record<string, SlideSize>>;
}

/** What `lib/deck` draws with: the themes beside mallow's, and the name a deck
 *  naming none — or one not held — falls back to. */
export interface DeckThemes {
  themes: readonly DeckTheme[];
  defaultName: string;
}

export const NO_DECK_THEMES: DeckThemes = Object.freeze({ themes: [], defaultName: MALLOW_THEME });

export interface FolderTheme extends DeckTheme {
  path: string;
  /** What the walk removed, for Settings rather than a deck's notice (§4). */
  removed: { atRules: string[]; assetUrls: number };
}

export type SkipReason = 'unreadable' | 'unparsed' | 'noTheme' | 'reserved' | 'conflict';

export interface SkippedFile {
  path: string;
  reason: SkipReason;
  /** The name the file claimed, for `reserved` and `conflict`. */
  name?: string;
}

export interface FolderThemes {
  themes: FolderTheme[];
  skipped: SkippedFile[];
}

/** One `.css` file of the folder, read or not. */
export type ThemeFile = { path: string; text: string } | { path: string; error: string };

export interface DefaultTheme {
  /** The theme a deck naming none is drawn with. */
  name: string;
  /** The stored preference when it names a theme not held, kept for Settings
   *  to show rather than rewritten (decision-19 §2). */
  missing: string | null;
}

/** The default-theme preference resolved against the names held: absent, it is
 *  mallow's slide theme, and so is a name no longer held. */
export function resolveDefaultTheme(preference: string | null | undefined, held: readonly string[]): DefaultTheme {
  if (!preference || preference === MALLOW_THEME) {
    return { name: MALLOW_THEME, missing: null };
  }
  return held.includes(preference) ? { name: preference, missing: null } : { name: MALLOW_THEME, missing: preference };
}
